# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""In-place foreach scalar subtraction (aten::_foreach_sub_.Scalar semantics).

Flat (contiguous / dense-permuted) tensors that share a dtype are processed by
ONE fused Triton launch: the grid covers the concatenation of their block ranges
and each program picks its tensor from a cumulative block-boundary chain. The
fused kernel has only four pointer slots so the per-launch host cost stays low;
when every length is a multiple of the tile the mask is dropped entirely, and
when every length is equal the boundaries are derived in-kernel.

fp16 and integer storage are subtracted in their own dtype (no widen/narrow
conversion pair in the streaming loop); fp32 and bf16 use fp32 opmath, which is
what ATen TensorIterator does and what measured best for those dtypes. The tile
is chosen as the largest power of two (up to 16384 elements) that divides every
length in the group, and non-divisible groups fall back to a masked 8192 tile.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 8192
_BLOCK_STRIDED = 1024
_SLOTS = 4


@triton.jit
def _tile_aligned(ptr, loc, sval, NATIVE: tl.constexpr, BLOCK: tl.constexpr):
    offs = loc * BLOCK + tl.arange(0, BLOCK)
    x = tl.load(ptr + offs)
    if NATIVE:
        y = x - sval.to(x.dtype)
    else:
        y = x.to(tl.float32) - sval.to(tl.float32)
    tl.store(ptr + offs, y)


@triton.jit
def _tile_masked(ptr, loc, n, sval, NATIVE: tl.constexpr, BLOCK: tl.constexpr):
    offs = loc * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(ptr + offs, mask=mask)
    if NATIVE:
        y = x - sval.to(x.dtype)
    else:
        y = x.to(tl.float32) - sval.to(tl.float32)
    tl.store(ptr + offs, y, mask=mask)


@triton.jit
def _tile_masked_ts(ptr, loc, n, S, NATIVE: tl.constexpr, BLOCK: tl.constexpr):
    offs = loc * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(ptr + offs, mask=mask)
    sv = tl.load(S)
    if NATIVE:
        y = x - sv.to(x.dtype)
    else:
        y = x.to(tl.float32) - sv.to(tl.float32)
    tl.store(ptr + offs, y, mask=mask)


@triton.jit
def _sub_fused_u(
    X0,
    X1,
    X2,
    X3,
    sval,
    nb,
    NATIVE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Uniform-length fuse: every tensor contributes the same `nb` blocks, so
    the boundaries are derived in-kernel and the launch carries only six args."""
    pid = tl.program_id(0)
    if pid < nb:
        _tile_aligned(X0, pid, sval, NATIVE, BLOCK)
    elif pid < 2 * nb:
        _tile_aligned(X1, pid - nb, sval, NATIVE, BLOCK)
    elif pid < 3 * nb:
        _tile_aligned(X2, pid - 2 * nb, sval, NATIVE, BLOCK)
    else:
        _tile_aligned(X3, pid - 3 * nb, sval, NATIVE, BLOCK)


@triton.jit
def _sub_fused4_aligned(
    X0,
    X1,
    X2,
    X3,
    sval,
    c1,
    c2,
    c3,
    NATIVE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    if pid < c1:
        _tile_aligned(X0, pid, sval, NATIVE, BLOCK)
    elif pid < c2:
        _tile_aligned(X1, pid - c1, sval, NATIVE, BLOCK)
    elif pid < c3:
        _tile_aligned(X2, pid - c2, sval, NATIVE, BLOCK)
    else:
        _tile_aligned(X3, pid - c3, sval, NATIVE, BLOCK)


@triton.jit
def _sub_fused4(
    X0,
    X1,
    X2,
    X3,
    sval,
    n0,
    n1,
    n2,
    n3,
    c1,
    c2,
    c3,
    NATIVE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    if pid < c1:
        _tile_masked(X0, pid, n0, sval, NATIVE, BLOCK)
    elif pid < c2:
        _tile_masked(X1, pid - c1, n1, sval, NATIVE, BLOCK)
    elif pid < c3:
        _tile_masked(X2, pid - c2, n2, sval, NATIVE, BLOCK)
    else:
        _tile_masked(X3, pid - c3, n3, sval, NATIVE, BLOCK)


@triton.jit
def _sub_one(
    X,
    sval,
    n,
    NATIVE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    _tile_masked(X, tl.program_id(0), n, sval, NATIVE, BLOCK)


@triton.jit
def _sub_one_ts(
    X,
    S,
    n,
    NATIVE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    _tile_masked_ts(X, tl.program_id(0), n, S, NATIVE, BLOCK)


@triton.jit
def _sub_strided_kernel(
    X,
    S,
    sval,
    n,
    sh0,
    sh1,
    sh2,
    sh3,
    sh4,
    sh5,
    sh6,
    sh7,
    st0,
    st1,
    st2,
    st3,
    st4,
    st5,
    st6,
    st7,
    ND: tl.constexpr,
    NATIVE: tl.constexpr,
    IS_TS: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    shp = (sh0, sh1, sh2, sh3, sh4, sh5, sh6, sh7)
    stp = (st0, st1, st2, st3, st4, st5, st6, st7)
    rem = offs
    off = tl.zeros([BLOCK], dtype=tl.int32)
    for k in tl.static_range(ND):
        sz = shp[k]
        idx = rem % sz
        rem = rem // sz
        off += idx * stp[k]
    x = tl.load(X + off, mask=mask)
    if IS_TS:
        sv = tl.load(S)
    else:
        sv = sval
    if NATIVE:
        y = x - sv.to(x.dtype)
    else:
        y = x.to(tl.float32) - sv.to(tl.float32)
    tl.store(X + off, y, mask=mask)


def _layout_dims(t):
    """None when the address set is exactly [0, numel) (flat kernel is valid),
    otherwise (size, stride) pairs sorted by increasing stride with contiguous
    neighbours merged."""
    if t.is_contiguous():
        return None
    shape = t.shape
    stride = t.stride()
    nd = len(shape)
    dims = [(shape[i], stride[i]) for i in range(nd) if shape[i] != 1]
    if not dims:
        return None
    if len(dims) == 1:
        return None if dims[0][1] == 1 else dims
    dims = [dims[i] for i in sorted(range(len(dims)), key=lambda i: dims[i][1])]
    merged = [list(dims[0])]
    for size, st in dims[1:]:
        last = merged[-1]
        if st == last[1] * last[0]:
            last[0] *= size
        else:
            merged.append([size, st])
    if len(merged) == 1 and merged[0][1] == 1:
        return None
    return merged


def _aliased(chunk):
    seen = []
    for t in chunk:
        sp = t.data_ptr()
        if sp in seen:
            return True
        seen.append(sp)
    return False


def _pick_block(counts, top_shift):
    """Largest power-of-two tile (<= 1 << top_shift) dividing every length, else
    0. All candidates are powers of two, so divisibility is a bitmask test."""
    for shift in range(top_shift, 9, -1):
        mask = (1 << shift) - 1
        for n in counts:
            if n & mask:
                break
        else:
            return 1 << shift
    return 0


def _cum(blocks, total):
    """_SLOTS-1 cumulative block boundaries; unused slots repeat `total` so
    their branches are unreachable."""
    cum = [total] * (_SLOTS - 1)
    acc = 0
    for k, b in enumerate(blocks):
        acc += b
        if k < _SLOTS - 1:
            cum[k] = acc
    return cum


def _launch_chunk(items, sval, native):
    """One launch for a chunk of <= _SLOTS flat tensors with a Number scalar."""
    size = len(items)
    counts = [t.numel() for t in items]
    ptrs = items + [items[0]] * (_SLOTS - size)
    top = 15 if items[0].dtype == torch.float16 else 14
    block = _pick_block(counts, top)
    if block:
        first = counts[0]
        uniform = True
        for n in counts:
            if n != first:
                uniform = False
                break
        if uniform:
            nb = first // block
            _sub_fused_u[(nb * size,)](
                ptrs[0],
                ptrs[1],
                ptrs[2],
                ptrs[3],
                sval,
                nb,
                NATIVE=native,
                BLOCK=block,
            )
            return
        blocks = [n // block for n in counts]
        total = 0
        for b in blocks:
            total += b
        _sub_fused4_aligned[(total,)](
            ptrs[0],
            ptrs[1],
            ptrs[2],
            ptrs[3],
            sval,
            *_cum(blocks, total),
            NATIVE=native,
            BLOCK=block,
        )
        return
    block = _BLOCK
    blocks = [(n + block - 1) // block for n in counts]
    total = 0
    for b in blocks:
        total += b
    counts += [1] * (_SLOTS - size)
    _sub_fused4[(total,)](
        ptrs[0],
        ptrs[1],
        ptrs[2],
        ptrs[3],
        sval,
        counts[0],
        counts[1],
        counts[2],
        counts[3],
        *_cum(blocks, total),
        NATIVE=native,
        BLOCK=block,
    )


def _launch_strided(t, sv, is_ts, native):
    n = t.numel()
    dims = _layout_dims(t)
    nd = len(dims)
    if nd > 8:
        raise RuntimeError("unsupported layout rank %d for in-place foreach sub" % nd)
    sizes = [1] * 8
    strides = [0] * 8
    for k in range(nd):
        sizes[k] = dims[k][0]
        strides[k] = dims[k][1]
    _sub_strided_kernel[((n + _BLOCK_STRIDED - 1) // _BLOCK_STRIDED,)](
        t,
        sv if is_ts else t,
        0.0 if is_ts else sv,
        n,
        sizes[0],
        sizes[1],
        sizes[2],
        sizes[3],
        sizes[4],
        sizes[5],
        sizes[6],
        sizes[7],
        strides[0],
        strides[1],
        strides[2],
        strides[3],
        strides[4],
        strides[5],
        strides[6],
        strides[7],
        ND=nd,
        NATIVE=native,
        IS_TS=is_ts,
        BLOCK=_BLOCK_STRIDED,
    )


def _launch_one(t, sv, is_ts, native):
    n = t.numel()
    grid = ((n + _BLOCK - 1) // _BLOCK,)
    if is_ts:
        _sub_one_ts[grid](t, sv, n, NATIVE=native, BLOCK=_BLOCK)
    else:
        _sub_one[grid](t, sv, n, NATIVE=native, BLOCK=_BLOCK)


def foreach_sub_scalar_(self, scalar):
    if isinstance(self, torch.Tensor):
        tensors = [self]
    elif isinstance(self, (list, tuple)):
        tensors = self
    else:
        raise TypeError(
            "_foreach_sub_ expects a list or tuple of Tensors, got %r" % (type(self),)
        )

    count = len(tensors)
    if count == 0:
        return None

    seq_scalar = isinstance(scalar, (list, tuple))
    if seq_scalar and len(scalar) != count:
        raise RuntimeError(
            "Tensor list length %d does not match scalar list length %d"
            % (count, len(scalar))
        )
    tensor_scalar = isinstance(scalar, torch.Tensor)

    groups = []
    index = {}
    for i in range(count):
        t = tensors[i]
        if t.numel() == 0:
            continue
        if seq_scalar:
            sv = scalar[i]
        else:
            sv = scalar
        is_ts = tensor_scalar or isinstance(sv, torch.Tensor)
        native = t.dtype == torch.float16 or not t.is_floating_point()
        if _layout_dims(t) is not None:
            _launch_strided(t, sv, is_ts, native)
            continue
        if is_ts:
            _launch_one(t, sv, True, native)
            continue
        key = (t.dtype, sv)
        slot = index.get(key)
        if slot is None:
            index[key] = slot = len(groups)
            groups.append((sv, native, []))
        groups[slot][2].append(t)

    for sv, native, items in groups:
        for start in range(0, len(items), _SLOTS):
            chunk = items[start : start + _SLOTS]
            if len(chunk) > 1 and _aliased(chunk):
                for t in chunk:
                    _launch_one(t, sv, False, native)
            else:
                _launch_chunk(chunk, sv, native)
    return None
